changeSet.sql:
-- started_at: use timestamp as default
ALTER TABLE transactions ALTER COLUMN started_at DROP NOT NULL;
ALTER TABLE transactions ALTER COLUMN started_at SET DEFAULT now();

-- state: default to FINISHED since we only save finished transactions
ALTER TABLE transactions ALTER COLUMN state DROP NOT NULL;
ALTER TABLE transactions ALTER COLUMN state SET DEFAULT 'FINISHED';

-- Make volume_litres and amount_cents nullable (we use volume_deciliters and amount_ore instead)
ALTER TABLE transactions ALTER COLUMN volume_litres DROP NOT NULL;
ALTER TABLE transactions ALTER COLUMN amount_cents DROP NOT NULL;
ALTER TABLE transactions ALTER COLUMN price_per_litre_cents DROP NOT NULL;

-- started_at: use timestamp as default
ALTER TABLE transactions ALTER COLUMN started_at SET DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE transactions ALTER COLUMN started_at SET NULL;

-- state: default to FINISHED since we only save finished transactions
ALTER TABLE transactions ALTER COLUMN state SET DEFAULT 'FINISHED';
ALTER TABLE transactions ALTER COLUMN state SET NULL;

-- Make volume_litres and amount_cents nullable
ALTER TABLE transactions ALTER COLUMN volume_litres SET NULL;
ALTER TABLE transactions ALTER COLUMN amount_cents SET NULL;
ALTER TABLE transactions ALTER COLUMN price_per_litre_cents SET NULL;
